.loading {
    opacity: 0.7;
    pointer-events: none;
}

/* 成功状态 */
.success {
    color: #4CAF50 !important;
}

/* 警告状态 */
.warning {
    color: #FF9800 !important;
}

/* 危险状态 */
.danger {
    color: #f5576c !important;
}"}

