// 应用主类
class SmokingAssistantApp {
    constructor() {
        this.storageManager = null;
        this.recordsManager = null;
        this.statsCalculator = null;
        this.uiManager = null;

        this.init();
    }

    /**
     * 初始化应用
     */
    init() {
        console.log('抽烟小助手正在启动...');

        // 检查浏览器兼容性
        if (!this.checkBrowserCompatibility()) {
            this.showCompatibilityWarning();
            return;
        }

        // 初始化模块
        this.initModules();

        // 启动应用
        this.start();

        console.log('抽烟小助手启动完成');
    }

    /**
     * 检查浏览器兼容性
     * @returns {boolean} 是否兼容
     */
    checkBrowserCompatibility() {
        // 检查LocalStorage
        try {
            localStorage.setItem('test', 'test');
            localStorage.removeItem('test');
        } catch (e) {
            console.error('LocalStorage不可用:', e);
            return false;
        }

        // 检查ES6特性
        if (typeof Promise === 'undefined') {
            console.error('Promise不可用');
            return false;
        }

        // 检查现代JavaScript特性
        if (typeof Object.assign === 'undefined') {
            console.error('Object.assign不可用');
            return false;
        }

        return true;
    }

    /**
     * 显示浏览器兼容性警告
     */
    showCompatibilityWarning() {
        const warningHTML = `
            <div style="
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0, 0, 0, 0.8);
                color: white;
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 9999;
                padding: 20px;
                text-align: center;
            ">
                <div style="max-width: 500px;">
                    <h2 style="color: #ff6b6b; margin-bottom: 20px;">
                        <i class="fas fa-exclamation-triangle"></i> 浏览器不兼容
                    </h2>
                    <p style="margin-bottom: 20px; line-height: 1.6;">
                        您的浏览器版本过旧，无法正常运行抽烟小助手。
                        请升级到最新版本的 Chrome、Firefox、Safari 或 Edge。
                    </p>
                    <div style="display: flex; gap: 15px; justify-content: center; margin-top: 30px;">
                        <a href="https://www.google.com/chrome/" 
                           target="_blank"
                           style="
                               background: #4285f4;
                               color: white;
                               padding: 10px 20px;
                               border-radius: 5px;
                               text-decoration: none;
                               display: flex;
                               align-items: center;
                               gap: 8px;
                           ">
                            <i class="fab fa-chrome"></i> Chrome
                        </a>
                        <a href="https://www.mozilla.org/firefox/" 
                           target="_blank"
                           style="
                               background: #ff7139;
                               color: white;
                               padding: 10px 20px;
                               border-radius: 5px;
                               text-decoration: none;
                               display: flex;
                               align-items: center;
                               gap: 8px;
                           ">
                            <i class="fab fa-firefox"></i> Firefox
                        </a>
                    </div>
                </div>
            </div>
        `;

        document.body.innerHTML = warningHTML;
    }

    /**
     * 初始化所有模块
     */
    initModules() {
        try {
            // 初始化存储管理器
            this.storageManager = StorageManager;

            // 初始化记录管理器
            this.recordsManager = RecordsManager;
            this.recordsManager.init(this.storageManager);

            // 初始化统计计算器
            this.statsCalculator = StatsCalculator;
            this.statsCalculator.init(this.recordsManager);

            // 初始化UI管理器
            this.uiManager = UIManager;

        } catch (error) {
            console.error('初始化模块失败:', error);
            throw new Error('应用初始化失败');
        }
    }

    /**
     * 启动应用
     */
    start() {
        try {
            // 初始化UI管理器
            this.uiManager.init(this.recordsManager, this.statsCalculator);

            // 添加启动动画
            this.addStartupAnimation();

            // 显示欢迎消息
            setTimeout(() => {
                this.showWelcomeMessage();
            }, 1000);

            // 添加页面可见性变化监听
            this.addVisibilityChangeListener();

            // 添加离线检测
            this.addOfflineDetection();

            // 添加服务工作者（如果支持）
            this.registerServiceWorker();

        } catch (error) {
            console.error('启动应用失败:', error);
            this.showErrorMessage('应用启动失败，请刷新页面重试');
        }
    }

    /**
     * 添加启动动画
     */
    addStartupAnimation() {
        // 为统计卡片添加渐入动画
        const statCards = document.querySelectorAll('.stat-card');
        statCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(20px)';

            setTimeout(() => {
                card.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
                card.style.opacity = '1';
                card.style.transform = 'translateY(0)';
            }, index * 100);
        });

        // 为按钮添加渐入动画
        const buttons = document.querySelectorAll('.btn-primary, .btn-secondary');
        buttons.forEach((button, index) => {
            button.style.opacity = '0';

            setTimeout(() => {
                button.style.transition = 'opacity 0.5s ease';
                button.style.opacity = '1';
            }, 500 + (index * 100));
        });
    }

    /**
     * 显示欢迎消息
     */
    showWelcomeMessage() {
        const todayRecords = this.recordsManager.getTodayRecords();

        if (todayRecords.length === 0) {
